  String translateCategoria(String slug, String fallback) {
    const slugToKey = {
      'evento': 'catEvento',
      'concerto': 'catConcerto',
      'ristorante': 'catRistorante',
      'servizio': 'catServizio',
      'vendita': 'catVendita',
      'sport': 'catSport',
      'cultura': 'catCultura',
      'lavoro': 'catLavoro',
      'altro': 'catAltro',
      'concert': 'catConcerto',
    };
    final key = slugToKey[slug];
    if (key == null) return fallback;
    final val = translate(key);
    return val == key ? fallback : val;
  }
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) {
    return ['it', 'en', 'es', 'ar', 'zh'].contains(locale.languageCode);
  }

  @override
  Future<AppLocalizations> load(Locale locale) async {
    return AppLocalizations(locale);
  }

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}
